-- V12.15: catálogo de 2.696 slots ativos PlayFiver adaptado do SQL legado fornecido pelo proprietário do projeto.
-- Não trunca tabelas, não altera logos de provedores e não reutiliza IDs do projeto antigo.
-- O par (provider_id, external_id) continua sendo a identidade única de cada jogo no MZ90.
SET NAMES utf8mb4;


ON DUPLICATE KEY UPDATE mode='PRODUCTION', api_source='PLAYFIVER';

DROP TEMPORARY TABLE IF EXISTS tmp_playfiver_slots_v1215;
CREATE TEMPORARY TABLE tmp_playfiver_slots_v1215 (
  sort_order INT NOT NULL,
  game_code VARCHAR(190) NOT NULL,
  game_name VARCHAR(190) NOT NULL,
  source_type VARCHAR(60) NULL,
  provider_code VARCHAR(60) NOT NULL,
  source_api VARCHAR(30) NOT NULL,
  source_distribution VARCHAR(60) NULL,
  image_url VARCHAR(500) NULL,
  featured TINYINT(1) NOT NULL DEFAULT 0,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (provider_code, game_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Desativa somente slots PlayFiver previamente importados por catálogo e ausentes na lista ativa fornecida.
-- Jogos PLAYFIVER cadastrados manualmente (source_type NULL/outro) não são afetados.
UPDATE casino_games g
JOIN casino_providers p ON p.id = g.provider_id
LEFT JOIN tmp_playfiver_slots_v1215 t
  ON t.provider_code = p.code AND t.game_code = g.external_id
SET g.enabled = 0, g.last_synced_at = NOW(6)
WHERE g.api_source = 'PLAYFIVER'
  AND g.category = 'SLOTS'
  AND g.source_type IN ('DOCUMENTED','CLONE')
  AND t.game_code IS NULL;

  provider_id,external_id,name,category,image_url,enabled,featured,sort_order,access_count,
  api_source,source_type,source_distribution,source_original,last_synced_at
)
SELECT
  p.id,t.game_code,t.game_name,'SLOTS',t.image_url,t.enabled,t.featured,t.sort_order,0,
  'PLAYFIVER',t.source_type,t.source_distribution,NULL,NOW(6)
FROM tmp_playfiver_slots_v1215 t
JOIN casino_providers p ON p.code = t.provider_code
ON DUPLICATE KEY UPDATE
  name = VALUES(name),
  category = 'SLOTS',
  image_url = VALUES(image_url),
  api_source = 'PLAYFIVER',
  source_type = VALUES(source_type),
  source_distribution = VALUES(source_distribution),
  source_original = NULL,
  last_synced_at = NOW(6);

DROP TEMPORARY TABLE IF EXISTS tmp_playfiver_slots_v1215;

